-- GENERATED by `wfj generate` from data/gossip/gossip-28.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["28004f27c880c17b"] = { "Le stagioni girano per tutti a tempo debito, ma tu sei ancora nella primavera della tua vita. Torna da noi più avanti, {class}, quando avrai più esperienza.", "." },
  ["28097f23f151f117"] = { "Dobbiamo agire in fretta o tutto sarà perduto!", "." },
  ["28140eb5c14eadb9"] = { "Halaan, ti prego, prestami il tuo dono.", "." },
  ["2814faec60514819"] = { "Ahhh, allora sei <pronto/pronta>...\n\nMetterò la mia roba nel braciere, allora, e potrai parlare con lo spirito anche tu.\n\nE non preoccuparti pe' niente di vedere nel mondo degli spiriti col sapta... il vecchio Tiev conosce un trucco o due su come funziona la magia del sapta.\n\nSu, vieni giù al santuario con me e parliamo insieme agli spiriti, <fratello/sorella>.", "." },
  ["283173c727846585"] = { "PERCHÉ? Perché è successo... proprio a me? Dov'eri, Tyrande? Dov'eri quando ho perso la grazia di Elune?", "." },
  ["2837dbb0fe2189f3"] = { "Ben fatto!", "." },
  ["284401110313613c"] = { "Sia la ⟦Lost Rigger Cove=Cala del Sartiame⟧ a Tanaris sia la ⟦Bay of Storms=Baia delle Tempeste⟧ ad Azshara hanno casse da scassinare per migliorare la tua abilità.", "." },
  ["2844fb40fd3d4ded"] = { "Nessuno sa davvero chi abbia creato le Carte di Lunacupa né quale sia il loro vero scopo, ma posso dirti che sono state trovate in tutta Azeroth, di solito nelle mani di qualche malvagio che cercava di svelarne i misteri.\n\nCi sono quattro tipi di Carte di Lunacupa: Bestie, Elementali, Portali e Signori della Guerra, con otto carte in ogni seme, dall'Asso all'Otto. Se raccogli tutte e otto le carte di un seme, puoi trasformarle in un mazzo da dare al nostro professor Thaddeus Paleo in cambio di un potente monile.", "." },
  ["2845a0d2eccfd7e8"] = { "Come vedi, non sono che un uomo con uno scudiero goffo e tonto. La potenza dei nani ⟦Dark Iron=Ferroscuro⟧ e delle bestie nella morsa di Ragnaros mi travolgerebbe di certo, da solo, ma ho la massima fiducia che una persona avventurosa, coraggiosa e ambiziosa come te non avrebbe problemi a sbarazzarsi degli abitanti del calderone. Se sceglierai di aiutarmi, ti ricompenserò con ricchezze oltre i tuoi sogni più sfrenati.", "." },
  ["284645aba18ce828"] = { "Scatola stupida. Lumurk ha sonno.", "." },
  ["2849dc425f6afe08"] = { "Gli occhi di %s si illuminano di rosso per un breve istante.", "." },
  ["284d4e07fdc3dcc5"] = { "Diversi set delle Plates of Uldum sono stati sintetizzati dai Creatori per il loro uso esplicito. I Creatori controllano la distribuzione di tali dischi per tutti i complessi di questo mondo. Di conseguenza, Azeroth è stata riprogrammata per una visita, e pertanto nuovi dischi potrebbero entrare in circolazione in quel momento.\n\nI dischi esistenti sono stati interamente distribuiti alle parti con adeguato nulla osta di sicurezza.", "." },
  ["28525910bc9dffeb"] = { "Probabilmente sentirai Tognus martellare sull'incudine quando sei a Kharanos. Però, se hai ancora le orecchie piene di cera, allora perché non dai semplicemente un'occhiata nella fucina?", "." },
  ["28559cc976a44897"] = { "%s intona: \"Assistilo in ogni modo che richiede. Non fallire in questo compito.\"", "." },
  ["2856e509a88861ed"] = { "Meglio che vada. Khara mi aspetterà presto. Ci vediamo domani X.", "." },
  ["285bac8d73a532a8"] = { "Voglio lasciare il mio famiglio nella stalla, stalliere.", "." },
  ["2875be427c4e9207"] = { "E questo è Comar Villard. Era sposato da due settimane quando sua moglie gli è stata strappata dalla sicurezza di ⟦Menethil Harbor=Porto di Menethil⟧.", "." },
  ["287e2a94cbdb1a3f"] = { "No uccidere me! No uccidere me!", "." },
  ["287f1b3c3c42fa79"] = { "Che bella giornata! Mi ispira a creare un nuovo modello.", "." },
  ["2886b5292add5ad5"] = { "Senti la furia delle sabbie!", "." },
  ["28899f23f278ee89"] = { "<Il nano impallidisce quando vede il barile vuoto.>\n\n...Dove l'hai trovato?", "." },
  ["28a6c6bfe0c56b13"] = { "Avvio rappresentazione visiva numero due.\n\nLa seconda varianza risultante della matrice dei Terrigeni conserva molti elementi desiderati rispetto alla matrice sotterranea standard. La nomenclatura comune per questa variante è \"Nano\".\n\nQuesta variante conserva la forza e il vigore propri dei Terrigeni. In alcuni casi, il nano supera perfino le capacità cognitive della matrice dei Terrigeni. Il nano, tuttavia, non conserva nulla della composizione fisica dei vari composti del nucleo di pietra di Azeroth.", "." },
  ["28a75f2116480794"] = { "ORA è il tempo dei Reietti! Potere ai Reietti, ORA E PER SEMPRE!!!", "." },
  ["28a7e5d5d24e3f07"] = { "Oh cielo! Che cos'è? Aiuto!", "." },
  ["28afe4876c61f2f6"] = { "Fate largo! Fate largo!", "." },
  ["28c3133154f25e30"] = { "Una maledizione mi perseguita! Prima affonda la mia nave, e ora... ho finito l'idromele!", "." },
  ["28c65a87b5ba952f"] = { "Allora, che ne pensi del mio nuovo giocattolo?", "." },
  ["28d190d65d563558"] = { "Alle forze Qiraji fu ordinato di ripiegare e di nascondere il grosso delle truppe sotto le sabbie del deserto. Fu ordinato un piccolo attacco contro ⟦Southwind Village=Vento del Sud⟧, mentre la prima linea dell'esercito di Staghelm veniva tenuta impegnata.", "." },
  ["28d47dc7db2d125e"] = { "Le notizie da ⟦Stormwind=Roccavento⟧ non promettono nulla di buono. . . .", "." },
  ["28d7b0833113d524"] = { "Alcuni argomenti su cui posso aiutarti sono: | driver | comandi | lag | bot....zzzzzzzzttt!!", "." },
  ["28de61b30d49dee0"] = { "Le mie ossa sono deboli, i miei occhi vedono solo oscurità e il mio corpo sente solo dolore; ma va bene così, perché la mia volontà è mia.", "." },
  ["28e1c40960d1c573"] = { "Mortale incosciente!", "." },
  ["28f3f62a99478c78"] = { "Azure Templar! Possiedo il tuo stemma di richiamo. Rispondi alla mia chiamata!", "." },
  ["28f4f57a46522564"] = { "Salute, {name}. Come procedono le tue ricerche nel demoniaco e nell'arcano? Hai scoperto qualche oscuro segreto di recente?", "." },
  ["28f65ef0f3de230e"] = { "Dov'è il mio filatoio? Ce l'avevo qui da qualche parte...", "." },
  ["28ff1fe89642aa2e"] = { "Sono Rutherford Twing, il principale fornitore dei Profanatori di stanza qui al ⟦Arathi Basin=Bacino d'Arathi⟧. Man mano che migliorerai la tua reputazione presso di noi, metterò a tua disposizione una bella selezione di merci che potrebbero tornarti utili. Se avessi bisogno di riparare qualche oggetto, offro anche quel servizio.", "." },
})
